/**
 * Geometry utilities for PDF parsing
 */
/**
 * Multiply two transformation matrices
 * Returns the concatenation a*b (apply b, then a).
 */
export declare function multiplyMatrix(a: number[], b: number[]): number[];
/**
 * Apply a transformation matrix to a point.
 */
export declare function transformPoint(m: number[], x: number, y: number): {
    x: number;
    y: number;
};
